mapper.select:
SELECT h.id AS hospitalId, h.name AS name, h.city AS city, h.district AS district, h.level AS level, h.hospital_type AS hospitalType, h.address AS address, h.booking_url AS bookingUrl, hd.department AS department, hd.specialty_level AS specialtyLevel, COALESCE(hd.source_url, h.source_url) AS sourceUrl, (h.source_url IS NOT NULL AND h.verified_at IS NOT NULL) AS verified, (hd.source_url IS NOT NULL AND hd.verified_at IS NOT NULL) AS departmentVerified FROM hospital h JOIN hospital_department hd ON hd.hospital_id = h.id WHERE h.status = 1
AND h.city = #{city}
AND hd.department = #{department}
ORDER BY (hd.specialty_level IS NULL), CASE WHEN hd.specialty_level LIKE '国家%' THEN 0 WHEN hd.specialty_level LIKE '省级%' THEN 1 ELSE 2 END, h.id LIMIT #{limit}
